style.css:
@-moz-document url-prefix("https://straw.page/draw") {
.intro {
    background-color: main
}

.intro img {
    filter: grayscale(100%) invert(1) brightness(1.3);
}


.first {
	background: linear-gradient(180deg, main 0%, gradient 100%) repeat scroll 0% 0% / auto padding-box border-box;
}

.kindaMenu button.selectedKinda, .kindaMenu button:hover, .uhh p, .siteViews, .shareSite, .feedPro:hover, .feedMeta, .traffic span, .gimmickTraffic .traffic span  {
	background:  main;
}

.kindaMenu button, .interlude {
	color: main;
	border: 2px solid main;
}

.sites > h4, .gimmicks > h4 {
	background: main;
    border: 2px solid #fff;
}

.mac p, .siteOptions button, .site, .outsideOptions, .post .meta, .post .content, .shareSplit i, .vidHold p    {
	color: main;
}

.feedPro {
	color:  main;
	border: 3px solid  main;
    background: highlight;
}

.newSite:hover {
	box-shadow: inset 0 0 0 2px main;
}

.newSite {
	background: main;
	border: 2px solid main;
}

.post {
	border: 2px solid main;
}

.post .meta {
	background: highlight;
	border-bottom: 2px solid main;
	color: main;
}

.post .meta img, .mac img {
	background-color: main;
    content: url(https://files.catbox.moe/oq9vho.png);
	border: 1px solid main;
}

.appIcon img {
	background-color: main;
    content: url(https://files.catbox.moe/oq9vho.png);
	border: 1px solid main;
}

.menu {
	background: rgba(main, 0.2);
	color: main;
}

.feedActionsInner, .sites select, .feedActionsTab button.selectedTab, .kindaMenu button[data-target="upgrade"] {
	background: highlight;
}

.sites, .mac, .sites select, .site iframe, .siteOptions, .siteViews, .shareSite, .shareSplit i {
	border: 2px solid main;
}

.feedActionsInner, .feedActionsTab button {
    border: 2px solid #fff;
    
}

.vidHold {
	border: 4px solid main;
}

.postExplain {
	border: 2px solid main;
	color: main;
}

.addPeople > p {
    color: main
}

.innerAddPeople i {
	background: main;
	border: 2px solid main;
}

.innerAddPeople input {
	border: 2px solid main;
	color: main;
}

.addingDon i:hover {
	background: main;
	color: #fff;
}

.addingDon i {
	border: 2px solid main;
	background: #fff;
	color: main;
}

.followingDon img {
	background-color: main;
    content: url(https://files.catbox.moe/oq9vho.png);
	border: 1px solid main;
}

/* gimmicks */

.followTop {
	border: 1px solid main;
	background: main;
}

.kindaMenu button span {
	background: main;
	color: #fff;
}

.reviewMode {
	border: 2px solid main;
	background: highlight;
	color: main;
}

.reviewMode button {
	border: 2px solid main;
	color: main;
}

.gimmickItem .asker, .gimmickItem .itemMenuOptions {
	color: main;
}

.gimmickTraffic {
	border-bottom: 2px solid main;
	color: main;
}

.gimmickItem {
	border: 2px solid main;
}

.gimmickItem .itemMenu {
	border-top: 2px solid main;
	color: main;
}
}
